SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">YAMUKTA TEMEL ÖZELLİKLER, ORTA TABAN VE ALAN BAĞINTISI</text>\n  <polygon points="110,65 250,65 310,195 50,195" fill="#eff6ff" stroke="#2563eb" stroke-width="2.5"/>\n  <line x1="80" y1="130" x2="280" y2="130" stroke="#dc2626" stroke-width="2.5" stroke-dasharray="5,3"/>\n  <line x1="110" y1="65" x2="110" y2="195" stroke="#16a34a" stroke-width="2" stroke-dasharray="4,3"/>\n  <rect x="110" y="183" width="12" height="12" fill="none" stroke="#16a34a" stroke-width="1.5"/>\n  <text x="100" y="60" font-size="12" font-weight="bold" fill="#1e293b">D</text>\n  <text x="255" y="60" font-size="12" font-weight="bold" fill="#1e293b">C</text>\n  <text x="38" y="205" font-size="12" font-weight="bold" fill="#1e293b">A</text>\n  <text x="316" y="205" font-size="12" font-weight="bold" fill="#1e293b">B</text>\n  <text x="65" y="134" font-size="12" font-weight="bold" fill="#dc2626">E</text>\n  <text x="286" y="134" font-size="12" font-weight="bold" fill="#dc2626">F</text>\n  <text x="180" y="58" text-anchor="middle" font-size="12" font-weight="bold" fill="#1d4ed8">c (üst taban)</text>\n  <text x="180" y="215" text-anchor="middle" font-size="12" font-weight="bold" fill="#1d4ed8">a (alt taban)</text>\n  <text x="190" y="124" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#dc2626">Orta Taban (e)</text>\n  <text x="122" y="155" font-size="12" font-weight="bold" fill="#15803d">h</text>\n  <rect x="355" y="50" width="315" height="185" rx="8" fill="#ffffff" stroke="#cbd5e1"/>\n  <text x="512" y="74" text-anchor="middle" font-size="13" font-weight="bold" fill="#1e293b">Yamuk Formülleri ([AB] // [DC])</text>\n  <text x="370" y="100" font-size="11" fill="#334155">• Yan kenar komşu açıları bütünlerdir:</text>\n  <text x="380" y="118" font-size="11" font-weight="bold" fill="#1d4ed8">m(A) + m(D) = 180°  ve  m(B) + m(C) = 180°</text>\n  <text x="370" y="143" font-size="11" fill="#334155">• Orta Taban Uzunluğu (|EF| = e):</text>\n  <text x="380" y="161" font-size="11" font-weight="bold" fill="#dc2626">2 · e = a + c   (Alt ve üst taban ortalaması)</text>\n  <text x="370" y="186" font-size="11" fill="#334155">• Yamuğun Alanı:</text>\n  <text x="380" y="204" font-size="11.5" font-weight="bold" fill="#15803d">Alan(ABCD) = e · h   (Orta taban × Yükseklik)</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">İKİZKENAR YAMUK VE DİK YAMUK ÖZELLİKLERİ</text>\n  <rect x="25" y="45" width="315" height="195" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="182" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">İkizkenar Yamuk (|AD| = |BC|)</text>\n  <polygon points="95,85 215,85 265,165 45,165" fill="#dbeafe" stroke="#1d4ed8" stroke-width="2"/>\n  <line x1="95" y1="85" x2="95" y2="165" stroke="#dc2626" stroke-width="1.8" stroke-dasharray="3,3"/>\n  <line x1="215" y1="85" x2="215" y2="165" stroke="#dc2626" stroke-width="1.8" stroke-dasharray="3,3"/>\n  <text x="155" y="80" text-anchor="middle" font-size="11" font-weight="bold" fill="#1e293b">c</text>\n  <text x="155" y="158" text-anchor="middle" font-size="11" font-weight="bold" fill="#1e293b">c</text>\n  <text x="70" y="180" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#dc2626">x</text>\n  <text x="240" y="180" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#dc2626">x</text>\n  <text x="40" y="200" font-size="10.5" fill="#334155">• Taban açıları ve köşegenler eşittir: |AC| = |BD|</text>\n  <text x="40" y="218" font-size="10.5" font-weight="bold" fill="#1e40af">• Ayak dikmeleri: 2 · x = a - c  ve  Alan = (a - x) · h</text>\n  <rect x="360" y="45" width="315" height="195" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="517" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Dik Yamuk ([AD] dik [AB])</text>\n  <polygon points="410,85 520,85 580,165 410,165" fill="#dcfce7" stroke="#15803d" stroke-width="2"/>\n  <line x1="520" y1="85" x2="520" y2="165" stroke="#dc2626" stroke-width="1.8" stroke-dasharray="3,3"/>\n  <rect x="410" y="153" width="12" height="12" fill="none" stroke="#15803d" stroke-width="1.5"/>\n  <rect x="520" y="153" width="12" height="12" fill="none" stroke="#dc2626" stroke-width="1.5"/>\n  <text x="398" y="130" font-size="11" font-weight="bold" fill="#15803d">h</text>\n  <text x="465" y="80" text-anchor="middle" font-size="11" font-weight="bold" fill="#1e293b">c</text>\n  <text x="550" y="179" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#dc2626">a - c</text>\n  <text x="375" y="200" font-size="10.5" fill="#334155">• C köşesinden dikme indirilerek dik üçgen kurulur.</text>\n  <text x="375" y="218" font-size="10.5" font-weight="bold" fill="#166534">• Köşegenler dik kesişirse ([AC] dik [BD]): h² = a · c</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">GENEL DÖRTGENLERDE KÖŞEGEN, KENAR VE ALAN İLİŞKİLERİ</text>\n  <rect x="25" y="50" width="315" height="185" rx="8" fill="#fefce8" stroke="#eab308"/>\n  <text x="182" y="75" text-anchor="middle" font-size="13" font-weight="bold" fill="#a16207">Köşegenleri Dik Kesişen Dörtgen</text>\n  <text x="40" y="103" font-size="11" fill="#334155">• ABCD dörtgeninde [AC] dik [BD] ise</text>\n  <text x="50" y="120" font-size="10.5" fill="#475569">karşılıklı kenarların kareleri toplamı eşittir:</text>\n  <text x="50" y="143" font-size="12" font-weight="bold" fill="#854d0e">a² + c² = b² + d²</text>\n  <text x="40" y="170" font-size="11" fill="#334155">• Köşegenleri dik kesişen dörtgenin alanı:</text>\n  <text x="50" y="190" font-size="11.5" font-weight="bold" fill="#854d0e">2 · Alan(ABCD) = |AC| · |BD|</text>\n  <rect x="360" y="50" width="315" height="185" rx="8" fill="#fef2f2" stroke="#ef4444"/>\n  <text x="517" y="75" text-anchor="middle" font-size="13" font-weight="bold" fill="#b91c1c">Orta Nokta (Varignon) ve Alan Kuralı</text>\n  <text x="375" y="103" font-size="11" fill="#334155">• Herhangi bir dörtgenin kenar orta noktaları</text>\n  <text x="385" y="120" font-size="10.5" fill="#475569">birleştirilirse oluşan KLMN şekli daima</text>\n  <text x="385" y="137" font-size="10.5" font-weight="bold" fill="#991b1b">PARALELKENARDIR.</text>\n  <text x="375" y="160" font-size="11" fill="#334155">• Çevre(KLMN) = |AC| + |BD|</text>\n  <text x="375" y="180" font-size="11" font-weight="bold" fill="#991b1b">• 2 · Alan(KLMN) = Alan(ABCD)</text>\n  <text x="375" y="202" font-size="10.5" fill="#334155">• Köşegenlerin ayırdığı 4 üçgen: S1 · S3 = S2 · S4</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
